R.append((7065016,
("Pastel de lentejas y parmesano con hierbas", "Este platillo fresco y sustancioso es alto en fibra y una buena fuente de carbohidratos.", "3", "301 g",
 ["100 g de harina de trigo todo uso", "1 cucharada de hierbas frescas picadas", "1 huevo pequeño, batido", "2 cucharadas de aceite de oliva", "2 cucharadas de agua", "1 cucharadita de aceite de oliva", "1 cebolla pequeña, picada", "1 diente de ajo, machacado", "medio pimiento rojo, picado", "100 g de coliflor, en ramitos", "1 calabacita pequeña, en rodajas", "1 tallo de apio, en rodajas", "1 zanahoria pequeña, rallada", "50 g de lentejas rojas", "1 lata de 400 g de tomates picados", "200 ml de caldo de verduras bajo en sal", "15 g de queso parmesano rallado", "1 cucharada de hierbas frescas mixtas, picadas", "pimienta negra recién molida"],
 ["Primero, prepare la masa. Ponga la harina en un tazón y, con un tenedor, mezcle las hierbas, el huevo, el aceite de oliva y el agua hasta formar una masa. Forme una bola con la masa y refrigérela por lo menos 30 minutos.", "Mientras tanto, precaliente el horno a 200 ºC (gas 6) y prepare el relleno. Caliente el aceite en una sartén grande, agregue la cebolla, el ajo y el pimiento y fría tres minutos, hasta que empiecen a ablandarse.", "Agregue la coliflor, la calabacita, el apio y la zanahoria y continúe friendo tres minutos.", "Agregue las lentejas, los tomates, el caldo, el queso parmesano, las hierbas y la pimienta. Deje que hierva y cocine a fuego lento 10 minutos, hasta que las verduras estén casi cocidas.", "Pase a un molde para pastel. Extienda la masa y cubra el pastel.", "Hornee de 25 a 30 minutos, hasta que la masa esté dorada y crujiente."],
 ["Puede hacerlo vegetariano usando una alternativa al parmesano o un poco de queso de cabra vegetariano.", "Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele en el refrigerador o en el microondas y recaliente hasta que esté muy caliente por completo.", "Porciones de fruta/verdura por porción: 3"], []),
("فطيرة العدس والبارميزان بالأعشاب", "طبق منعش ومشبع غني بالألياف ومصدر جيد للكربوهيدرات.", "3", "301 غ",
 ["100 غ دقيق عادي", "1 ملعقة كبيرة أعشاب طازجة مفرومة", "1 بيضة صغيرة، مخفوقة", "2 ملعقة كبيرة زيت زيتون", "2 ملعقة كبيرة ماء", "1 ملعقة صغيرة زيت زيتون", "1 حبة بصل صغيرة، مفرومة", "1 فص ثوم، مهروس", "نصف حبة فلفل رومي أحمر، مفرومة", "100 غ قرنبيط، مقطع إلى زهيرات", "1 حبة كوسا صغيرة، مقطعة شرائح", "1 ساق كرفس، مقطعة شرائح", "1 حبة جزر صغيرة، مبشورة", "50 غ عدس أحمر", "1 علبة 400 غ طماطم مقطعة", "200 مل مرق خضار قليل الملح", "15 غ جبن بارميزان مبشور", "1 ملعقة كبيرة أعشاب طازجة مشكّلة، مفرومة", "فلفل أسود مطحون طازجًا"],
 ["أولًا، حضّر العجينة. ضع الدقيق في وعاء واخلط بالشوكة الأعشاب والبيض وزيت الزيتون والماء حتى تتكوّن عجينة. شكّل العجينة على هيئة كرة وضعها في الثلاجة 30 دقيقة على الأقل.", "في هذه الأثناء، سخّن الفرن مسبقًا إلى 200° مئوية (علامة الغاز 6) وحضّر الحشوة. سخّن الزيت في مقلاة كبيرة، وأضف البصل والثوم والفلفل وقلّبها ثلاث دقائق حتى تبدأ بالذبول.", "أضف القرنبيط والكوسا والكرفس والجزر وواصل التقليب ثلاث دقائق.", "أضف العدس والطماطم والمرق وجبن البارميزان والأعشاب والفلفل. اتركها حتى تغلي ثم اتركها على نار هادئة 10 دقائق حتى تكاد الخضار تنضج.", "انقلها إلى طبق فطيرة. افرد العجينة وغطِّ بها الفطيرة.", "اخبزها من 25 إلى 30 دقيقة حتى تصبح العجينة ذهبية ومقرمشة."],
 ["يمكنك جعلها نباتية باستخدام بديل للبارميزان أو قليل من جبن الماعز النباتي.", "تعليمات التجميد: يمكن تجميدها بعد الطهي. أذبها في الثلاجة أو في الميكروويف ثم أعد تسخينها حتى تصبح ساخنة تمامًا من الداخل.", "حصص الفاكهة/الخضار في الحصة الواحدة: 3"], [])))
R.append((7066965,
("Pizza de verduras", "Varíe los ingredientes y cree su propia pizza vegetariana.", "4", "292 g",
 ["1 cucharada de aceite de oliva", "1 cebolla morada grande, cortada por la mitad y en rebanadas", "1 pimiento rojo y 1 amarillo, sin semillas y cortados en trozos", "100 g de champiñones, en rebanadas", "1 cucharadita rasa de albahaca seca", "1 cucharadita colmada de orégano seco", "3 a 4 dientes de ajo, machacados", "2 buenas molidas de pimienta negra", "4 tomates secos, picados finamente", "2 a 3 tomates frescos, picados", "2 panes naan grandes sin sabor (130 g cada uno)", "1 bola de 125 g de mozzarella reducida en grasa", "en rebanadas finas", "8 a 10 hojas de albahaca fresca, para servir"],
 ["Precaliente el horno a 200 ºC (gas 6). Agregue el aceite de oliva a la sartén con la cebolla y cocine 2 minutos. Luego agregue los pimientos y los champiñones y revuelva con frecuencia de 7 a 8 minutos, cuidando que se cocinen de manera uniforme.", "Agregue la albahaca, el orégano, el ajo, una molida de pimienta negra y los tomates secos y frescos. Mezcle bien, deje que hierva, baje el fuego, tape y cocine a fuego lento 5 minutos.", "Coloque los panes naan en una bandeja para hornear y distribuya las verduras y el queso mozzarella de manera uniforme encima. Hornee unos 8 a 10 minutos (hasta que el queso se derrita y los bordes del naan estén ligeramente dorados).", "Espolvoree con hojas de albahaca fresca y pimienta negra antes de servir."],
 ["Al cocinar primero las verduras, le cabrán muchas más en la pizza. Así la comida es más saludable y más sabrosa.", "Puede guardar un par de panes naan en el congelador y usar diferentes combinaciones de verduras, incluso sobras. Si no tiene mozzarella reducida en grasa, el queso Cheddar reducido en grasa también funciona bien.", "Instrucciones para congelar: Congele en papel encerado. Descongele 1 hora y luego hornee como de costumbre.", "Porciones de fruta/verdura por porción: 2"], []),
("بيتزا الخضار", "نوّع الإضافات وصمّم بيتزا الخضار الخاصة بك.", "4", "292 غ",
 ["1 ملعقة كبيرة زيت زيتون", "1 حبة بصل أحمر كبيرة، مقسومة نصفين ثم مقطعة شرائح", "1 حبة فلفل رومي أحمر و1 أصفر، منزوعة البذور ومقطعة قطعًا", "100 غ فطر، مقطع شرائح", "1 ملعقة صغيرة مستوية ريحان مجفف", "1 ملعقة صغيرة مكوّمة أوريغانو مجفف", "3-4 فصوص ثوم، مهروسة", "2 رشة جيدة من الفلفل الأسود المطحون", "4 حبات طماطم مجففة بالشمس، مفرومة ناعمًا", "2-3 حبات طماطم طازجة، مقطعة", "2 رغيف نان عادي كبير (130 غ لكل رغيف)", "1 كتلة 125 غ موزاريلا قليلة الدسم", "مقطعة شرائح رفيعة", "8-10 أوراق ريحان طازج، للتقديم"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية (علامة الغاز 6). ضع زيت الزيتون في المقلاة مع البصل واطبخه دقيقتين. بعد ذلك، أضف الفلفل والفطر وحرّك باستمرار من 7 إلى 8 دقائق مع التأكد من نضجها بالتساوي.", "أضف الريحان والأوريغانو والثوم ورشة من الفلفل الأسود والطماطم المجففة والطازجة. امزج جيدًا واتركها حتى تغلي، ثم خفّض الحرارة وضع الغطاء واتركها على نار هادئة 5 دقائق.", "ضع أرغفة النان على صينية الخَبز ووزّع الخضار وجبن الموزاريلا بالتساوي فوقها. اخبزها في الفرن حوالي 8 إلى 10 دقائق (حتى يذوب الجبن وتصبح حواف النان بنية فاتحة).", "رشّ أوراق الريحان الطازجة والفلفل الأسود قبل التقديم."],
 ["بطهي الخضار أولًا يمكنك وضع كمية أكبر بكثير منها على البيتزا، فتصبح الوجبة أكثر صحة وألذّ طعمًا.", "يمكنك الاحتفاظ برغيفَي نان في الفريزر واستخدام تشكيلات مختلفة من الخضار، حتى بقايا الطعام. وإن لم يتوفر لديك موزاريلا قليلة الدسم، فجبن الشيدر قليل الدسم يعطي نتيجة جيدة.", "تعليمات التجميد: جمّدها ملفوفة بورق مقاوم للدهون. أذبها ساعة واحدة ثم اخبزها كالمعتاد.", "حصص الفاكهة/الخضار في الحصة الواحدة: 2"], [])))
R.append((7067962,
("Guiso de frijoles blancos y cordero", "Este es un platillo campestre sustancioso, fácil de preparar y muy satisfactorio. También puede congelar las sobras.", "4", "423 g",
 ["aceite de oliva en aerosol", "300 g de cordero muy magro, en cubos", "1 cebolla, picada en trozos grandes", "2 tallos de apio, cortados en trozos de 2 cm", "2 zanahorias, peladas y cortadas en trozos de 2 cm", "2 dientes de ajo, en rebanadas", "2 ramitas de romero", "1 cucharada de salsa Worcestershire", "1 lata de 410 g de tomates picados", "2 hojas de laurel", "1 lata de 820 g de frijoles caritas en agua, escurridos y enjuagados", "300 g de col de Saboya, picada en trozos grandes", "pimienta negra molida"],
 ["Precaliente el horno a 180 ºC (gas 4).", "Caliente a fuego alto una cazuela resistente al fuego, rocíe ligeramente con aceite de oliva y fría el cordero por tandas hasta que se dore por todos lados. Reserve.", "En la misma cazuela, agregue la cebolla, el apio, las zanahorias, el ajo y el romero y cocine, agregando un chorrito de agua, hasta que las verduras empiecen a ablandarse (aprox. 10 minutos).", "Regrese el cordero a la cazuela y agregue la salsa Worcestershire, los tomates y las hojas de laurel. Revuelva para integrar y agregue 300 ml de agua.", "Tape y hornee 45 minutos. Incorpore los frijoles y la col, agregando más agua si es necesario.", "Regrese al horno 15 minutos más."],
 ["Puede preparar este platillo con cerdo magro o res.", "Pruebe otros frijoles, como borlotti, cannellini o alubias blancas.", "Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele en el refrigerador o en el microondas y recaliente en el horno o en el microondas hasta que esté muy caliente.", "Porciones de fruta/verdura por porción: 4"], []),
("يخنة الفاصولياء البيضاء ولحم الضأن", "طبق ريفي دسم، سهل التحضير ومشبع جدًا. يمكنك أيضًا تجميد أي بقايا.", "4", "423 غ",
 ["بخاخ زيت زيتون", "300 غ لحم ضأن قليل الدهن جدًا، مقطع مكعبات", "1 حبة بصل، مقطعة قطعًا كبيرة", "2 ساق كرفس، مقطعة قطعًا بطول 2 سم", "2 حبة جزر، مقشّرة ومقطعة قطعًا بطول 2 سم", "2 فص ثوم، مقطعة شرائح", "2 غصن إكليل الجبل (روزماري)", "1 ملعقة كبيرة صلصة ورسيستر", "1 علبة 410 غ طماطم مقطعة", "2 ورقة غار", "1 علبة 820 غ لوبيا عيون سوداء في الماء، مصفّاة ومشطوفة", "300 غ ملفوف سافوي، مقطع قطعًا كبيرة", "فلفل أسود مطحون"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (علامة الغاز 4).", "سخّن قدرًا يتحمل النار على حرارة عالية، ورشّه برفق ببخاخ زيت الزيتون، ثم قلّب لحم الضأن على دفعات حتى يحمرّ من جميع الجهات. ضعه جانبًا.", "في القدر نفسه، أضف البصل والكرفس والجزر والثوم وإكليل الجبل واطبخها مع إضافة رشة ماء حتى تبدأ الخضار بالذبول (حوالي 10 دقائق).", "أعد لحم الضأن إلى القدر وأضف صلصة ورسيستر والطماطم وورق الغار. حرّك لتمتزج المكونات وأضف 300 مل ماء.", "غطِّ القدر واطبخ في الفرن 45 دقيقة. أضف الفاصولياء والملفوف وحرّك، مع إضافة ماء إضافي عند الحاجة.", "أعده إلى الفرن 15 دقيقة أخرى."],
 ["يمكنك تحضير هذا الطبق بلحم الخنزير قليل الدهن أو لحم البقر.", "جرّب أنواعًا أخرى من الفاصولياء مثل البورلوتي أو الكانليني أو الفاصولياء البيضاء الصغيرة.", "تعليمات التجميد: يمكن تجميدها بعد الطهي. أذبها في الثلاجة أو الميكروويف ثم أعد تسخينها في الفرن أو الميكروويف حتى تصبح ساخنة جدًا.", "حصص الفاكهة/الخضار في الحصة الواحدة: 4"], [])))
R.append((7068047,
("Adornos de pan de jengibre", "Adornos comestibles y divertidos para preparar con los niños. Las estrellas o campanas lucen muy bien colgadas en el árbol y duran de 2 a 3 semanas, ¡si logra resistirse tanto tiempo!", "20", "12 g",
 ["1 huevo", "50 ml de aceite de canola", "10 a 12 cucharaditas de edulcorante artificial granulado", "125 g de harina integral", "media cucharadita de polvo para hornear", "2 cucharaditas de jengibre molido", "spray o pintura comestible dorada"],
 ["Precaliente el horno a 180 ºC (gas 4).", "Bata el huevo en un tazón. Agregue el aceite y el edulcorante artificial y mezcle bien.", "Incorpore la harina, el polvo para hornear y el jengibre, y mezcle de nuevo.", "Extienda la masa hasta que tenga aproximadamente 1 cm de grosor y corte las formas que elija. Si las va a colgar en el árbol, haga con cuidado un agujero para el listón en un extremo con un palillo largo o un palillo chino. Extienda la masa sobrante y siga cortando más formas.", "Colóquelas en una bandeja para hornear ligeramente engrasada y hornee de 8 a 10 minutos.", "Páselas a una rejilla para que se enfríen y decore con la pintura plateada o dorada. Pase los listones por los agujeros y haga un nudo para formar un lazo. Cuélguelas en su árbol."],
 ["Si va a colgar las galletas, después de 3 a 4 minutos de cocción revise que los agujeros sigan abiertos y, si es necesario, vuelva a pasar con cuidado el palillo por ellos mientras las galletas siguen en la bandeja.", "Puede agregar canela o una pizca de clavo para darles un sabor diferente.", "Porciones de fruta/verdura por porción: 0"], []),
("زينة خبز الزنجبيل", "زينة صالحة للأكل وممتعة لتحضيرها مع الأطفال. تبدو النجوم أو الأجراس رائعة معلّقة على الشجرة وتدوم من 2 إلى 3 أسابيع، إن استطعتم مقاومتها كل هذه المدة!", "20", "12 غ",
 ["1 بيضة", "50 مل زيت اللفت (الكانولا)", "10-12 ملعقة صغيرة محلّي صناعي محبّب", "125 غ دقيق القمح الكامل", "نصف ملعقة صغيرة بيكنغ باودر", "2 ملعقة صغيرة زنجبيل مطحون", "بخاخ أو طلاء ذهبي صالح للأكل"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (علامة الغاز 4).", "اخفق البيضة في وعاء. أضف الزيت والمحلّي الصناعي وامزج جيدًا.", "أضف الدقيق والبيكنغ باودر والزنجبيل وحرّك، ثم امزج مرة أخرى.", "افرد الخليط بسماكة 1 سم تقريبًا واقطع الأشكال التي تريدها. وإذا كنت ستعلّقها على الشجرة، فاصنع بحرص ثقبًا لشريط الزينة في أحد الأطراف بسيخ أو بعود صيني. افرد العجين المتبقي واقطع المزيد من الأشكال.", "ضعها على صينية خَبز مدهونة بقليل من الزيت واخبزها من 8 إلى 10 دقائق.", "ضعها على رف لتبرد وزيّنها بالطلاء الفضي أو الذهبي. أدخل الأشرطة في الثقوب واعقدها لتكوّن عروة. علّقها على شجرتك."],
 ["إذا كنت ستعلّق البسكويت، فبعد 3 إلى 4 دقائق من الخَبز تأكد من أن الثقوب ما زالت مفتوحة، وإذا لزم الأمر فمرّر السيخ أو العود بحرص مرة أخرى وهي ما زالت على الصينية.", "يمكنك إضافة القرفة أو رشة من القرنفل للحصول على نكهة مختلفة.", "حصص الفاكهة/الخضار في الحصة الواحدة: 0"], [])))
R.append((7071862,
("Avena cocida con muchas bayas", "Comience el día con avena cocida y bayas por encima, un desayuno que lo mantendrá satisfecho por más tiempo.", "1", "256 g",
 ["50 g de avena en hojuelas", "6 fresas, en rebanadas", "6 frambuesas", "15 arándanos azules", "100 ml de leche descremada", "2 cucharaditas de almendras laminadas tostadas"],
 ["Ponga la avena y 250 ml de agua en una olla. Deje que hierva, baje el fuego y revuelva con frecuencia de 4 a 5 minutos.", "Incorpore tres cuartas partes de la fruta y agregue la leche.", "Suba el fuego otra vez, mezcle bien y pase a un tazón.", "Cubra con el resto de la fruta y las almendras, y sirva."],
 ["Esta avena también queda muy bien con manzanas picadas, unas pasas y una buena pizca de canela molida.", "Puede usar avena sin gluten u otros cereales en hojuelas, como mijo, alforfón o arroz, que se consiguen en tiendas de productos naturales.", "Porciones de fruta/verdura por porción: 1"], []),
("عصيدة الشوفان بالتوت المشكّل", "ابدأ يومك بعصيدة الشوفان مع التوت، فهي وجبة فطور تُبقيك ممتلئًا لفترة أطول.", "1", "256 غ",
 ["50 غ شوفان مجروش", "6 حبات فراولة، مقطعة شرائح", "6 حبات توت العليق", "15 حبة توت أزرق", "100 مل حليب خالٍ من الدسم", "2 ملعقة صغيرة لوز مقطّع شرائح ومحمّص"],
 ["ضع الشوفان و250 مل من الماء في قدر. اتركه حتى يغلي ثم خفّض الحرارة وحرّك باستمرار من 4 إلى 5 دقائق.", "أضف ثلاثة أرباع الفاكهة وأضف الحليب وحرّك.", "ارفع الحرارة مرة أخرى وامزج جيدًا ثم ضعه في وعاء.", "زيّنه ببقية الفاكهة واللوز ثم قدّمه."],
 ["هذه العصيدة رائعة أيضًا مع التفاح المقطّع وقليل من الزبيب ورشة كبيرة من القرفة المطحونة.", "يمكنك استخدام شوفان خالٍ من الغلوتين أو حبوب مجروشة أخرى مثل الدخن أو الحنطة السوداء أو الأرز، وهي متوفرة في متاجر الأغذية الصحية.", "حصص الفاكهة/الخضار في الحصة الواحدة: 1"], [])))
R.append((7075143,
("Dedos de tofu empanizados", "Deliciosos dedos veganos sin gluten, perfectos para una cena rápida.", "2", "162 g",
 ["1 cucharadita de aceite de girasol", "50 ml de leche de coco", "1 cucharada de harina de garbanzo", "1 cucharadita colmada de polvo de cinco especias chino", "50 g de pan molido integral sin gluten", "200 g de tofu firme, cortado en tiras"],
 ["Precaliente el horno a 190 ° (gas 5). Engrase ligeramente una bandeja para hornear y ponga la leche de coco en un tazón poco profundo. Mezcle la harina con las cinco especias; luego ponga la harina en un plato llano y el pan molido en otro.", "Ponga el tofu en el plato con la harina y mezcle para que cada pieza quede cubierta, separando las tiras para que no se toquen entre sí.", "Lávese y séquese las manos; luego tome una tira de tofu, sacuda el exceso de harina, sumérjala en la leche de coco y colóquela sobre el pan molido; espolvoree más pan molido encima para cubrir por completo el tofu y luego pásela a la bandeja. Repita hasta cubrir todos los dedos de tofu.", "Hornee 15 minutos, hasta que el exterior esté crujiente y ligeramente dorado."],
 ["Conviene usar una mano para sumergir los dedos en la leche de coco y la otra para empanizar los trocitos; de lo contrario, puede ensuciarse mucho.", "Para hacer pan molido, seque un par de rebanadas de pan en el horno durante unos minutos, rompa en trozos más pequeños y luego use una licuadora o una batidora de inmersión para molerlo. Si aún se siente húmedo y grumoso, extiéndalo en una bandeja para hornear y déjelo un par de minutos más antes de volver a licuarlo.", "Agregue especias como pimentón ahumado, comino o curry a la harina o al pan molido para dar más sabor.", "Porciones de fruta/verdura por porción: 0"], []),
("أصابع التوفو المقرمشة", "أصابع لذيذة نباتية وخالية من الغلوتين، مثالية لوجبة خفيفة سريعة.", "2", "162 غ",
 ["1 ملعقة صغيرة زيت دوار الشمس", "50 مل حليب جوز الهند", "1 ملعقة كبيرة دقيق الحمص", "1 ملعقة صغيرة مكوّمة مسحوق التوابل الخمسة الصيني", "50 غ فتات خبز القمح الكامل الخالي من الغلوتين", "200 غ توفو صلب، مقطع إلى شرائح"],
 ["سخّن الفرن مسبقًا إلى 190° (علامة الغاز 5). ادهن صينية الخَبز بقليل من الزيت وضع حليب جوز الهند في وعاء واسع قليل العمق. اخلط الدقيق مع التوابل الخمسة، ثم ضع الدقيق في طبق مسطح وفتات الخبز في طبق مسطح آخر.", "ضع التوفو في طبق الدقيق وقلّبه ليتغطى كل جزء، مع فصل الشرائح بحيث لا تتلامس.", "اغسل يديك وجففهما ثم التقط شريحة من التوفو، وانفض عنها الدقيق الزائد، واغمسها في حليب جوز الهند ثم ضعها على فتات الخبز وانثر المزيد من الفتات فوقها لتغطية التوفو بالكامل، ثم ضعها على صينية الخَبز. كرّر ذلك حتى تُغطّى كل أصابع التوفو.", "اخبزها 15 دقيقة حتى يصبح الخارج مقرمشًا وبنيًا فاتحًا."],
 ["من الأفضل استخدام يد واحدة لغمس الأصابع في حليب جوز الهند والأخرى لتغطيتها بفتات الخبز، وإلا قد تتسخ يداك كثيرًا.", "لتحضير فتات الخبز، جفّف شريحتين من الخبز في الفرن لبضع دقائق، وكسّرهما إلى قطع أصغر، ثم استخدم الخلاط أو الخلاط اليدوي لطحن الخبز. وإذا بقي رطبًا ومتكتلًا، فافرده على صينية خَبز واتركه دقيقتين إضافيتين قبل أن تطحنه مرة أخرى.", "أضف توابل مثل البابريكا المدخنة أو الكمون أو الكاري إلى الدقيق أو فتات الخبز لإضافة نكهة أكثر.", "حصص الفاكهة/الخضار في الحصة الواحدة: 0"], [])))
